  .main-content,
  #main.no-sub-about,
  #main.no-sub-about .no-sub-about-contents,
  #main.no-sub-about .no-sub-about-hero,
  #main.no-sub-about .no-sub-about-hero__inner,
#main.no-sub-about .no-sub-about-vision,
  #main.no-sub-about .no-sub-about-vision__inner {
    pointer-events: none;
  }
}

